package org.mockito.internal.stubbing.defaultanswers;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockSettings;
import org.mockito.internal.InternalMockHandler;
import org.mockito.internal.MockitoCore;
import org.mockito.internal.bytecode.mockmaker.MockMaker;
import org.mockito.internal.creation.settings.CreationSettings;
import org.mockito.internal.stubbing.InvocationContainerImpl;
import org.mockito.internal.stubbing.OngoingStubbing;
import org.mockito.internal.stubbing.StubbedInvocationMatcher;
import org.mockito.internal.util.MockUtil;
import org.mockito.internal.util.generic.GenericMetadataSupport;
import org.mockito.internal.util.reflection.GenericMetadataSupport;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ReturnsDeepStubs_answer_TriageGen1Test {

    private ReturnsDeepStubs returnsDeepStubs;
    private InvocationOnMock invocation;
    private MockMaker mockitoCore;
    private OngoingStubbing<?> delegate;

    // Stubbed subclass to expose protected method for testing
    public static class TestableReturnsDeepStubs extends ReturnsDeepStubs {
        private final GenericMetadataSupport metadataToReturn;

        public TestableReturnsDeepStubs(GenericMetadataSupport metadataToReturn, OngoingStubbing<?> delegate) {
            super();
            this.metadataToReturn = metadataToReturn;
            this.delegate = delegate;
        }

        @Override
        protected GenericMetadataSupport actualParameterizedType(Object mock) {
            return metadataToReturn;
        }

        // Mocking the internal behavior of getMock and delegate via field or override if necessary
        // Since we cannot easily override getMock (it's private/protected), 
        // we rely on the logic flow.

        public Object answerWithMock(InvocationOnMock invocation) throws Throwable {
            return super.answer(invocation);
        }
    }

    // We use a spy or a specialized subclass to control the protected method 'actualParameterizedType'
    // and mock the internal dependencies.

    private GenericMetadataSupport mockMetadata;
    private Class<?> mockRawType;
    private Object expectedReturnValue;
    private Object expectedMockReturn;

    @Before
    public void setUp() throws Exception {
        invocation = mock(InvocationOnMock.class);
        mockitoCore = mock(MockMaker.class);
        delegate = mock(OngoingStubbing.class);
        mockMetadata = mock(GenericMetadataSupport.class);
        mockRawType = String.class;

        // We need to instantiate the class under test. 
        // Since we can't easily mock 'getMock' (it's private), we will use a partial mock/spy approach.
        returnsDeepStubs = new TestableReturnsDeepStubs(mockMetadata, delegate) {
            @Override
            protected Object getMock(InvocationOnMock invocation, GenericMetadataSupport metadata) {
                return expectedMockReturn;
            }
        };
    }

    @Test
    public void testAnswer_WhenTypeIsNotMockable() throws Throwable {
        // Arrange
        Object mockObject = new Object();
        Method method = String.class.getMethod("length");

        when(invocation.getMock()).thenReturn(mockObject);
        when(invocation.getMethod()).thenReturn(method);
        when(mockMetadata.rawType()).thenReturn(String.class);
        when(mockitoCore.isTypeMockable(String.class)).thenReturn(false);
        when(delegate.returnValueFor(String.class)).thenReturn("not-a-mock");

        // We need to inject the mockitoCore and delegate into the instance. 
        // Since they are private fields in the real class, we use reflection for the test.
        setField(returnsDeepStubs, "mockitoCore", mockitoCore);
        setField(returnsDeepStubs, "delegate", delegate);

        // Act
        Object result = returnsDeepStubs.answer(invocation);

        // Assert
        assertEquals("not-a-mock", result);
    }

    @Test
    public void testAnswer_WhenTypeIsMockable() throws Throwable {
        // Arrange
        Object mockObject = new Object();
        Method method = String.class.getMethod("length");
        expectedMockReturn = "mocked-object";

        when(invocation.getMock()).thenReturn(mockObject);
        when(invocation.getMethod()).thenReturn(method);
        when(mockMetadata.rawType()).thenReturn(String.class);
        when(mockitoCore.isTypeMockable(String.class)).thenReturn(true);

        setField(returnsDeepStubs, "mockitoCore", mockitoCore);
        setField(returnsDeepStubs, "delegate", delegate);

        // Act
        Object result = returnsDeepStubs.answer(invocation);

        // Assert
        assertSame(expectedMockReturn, result);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getSuperclass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}
